    const seen = s[y * m.w + xx] === '1'; const c = m.rows[y][xx];
    const k = xx + ',' + y; x.fillStyle = !seen ? '#1a1f38' : m.doors[k] ? '#e8c070' : m.block.has(k) ? '#8a4a3a' : MINI_COL[c] || '#3f7a36';
    x.fillRect(ox + xx * sc, oy + y * sc, sc, sc);
